            st.marks.add(new window.Konva.Circle({ x: c.x + r * 0.2 + i * r * 0.14, y: c.y - r * 0.24, radius: r * 0.06, fill: pois[i].color, stroke: "#000", strokeWidth: 1, listening: false }));
